use vstd::prelude::*;

verus! {

fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        result@ == a@,
        result@.len() == a@.len(),
{
    let mut result: Vec<T> = Vec::with_capacity(a.len());

    for &x in a.iter()
        invariant
            // The result is always a prefix-copy of `a`
            result@ == a@.subrange(0, result@.len() as int),
            result@.len() <= a@.len(),
        ensures
            result@ == a@,
    {
        // At loop head we know `result` is a prefix of `a`.
        // The next pushed element corresponds to `a[result.len()]`.
        assert(result@.len() < a@.len());

        // Relate the iterator element `x` to the element in `a` at the current index.
        // (Verus's standard library provides the connection between iteration order and sequence order.)
        assert(x == a@[result@.len() as int]);

        result.push(x);

        // Re-establish the prefix invariant after push.
        assert(result@ == a@.subrange(0, result@.len() as int));
    }

    result
}

} // verus!

